using System;
using System.IO;
using System.Reflection;
using System.Windows;
using System.Windows.Media;
using System.Windows.Media.Imaging;
using System.Windows.Threading;
class RunPreviewTests {
 static int failures;static object Get(object o,string n){return o.GetType().GetField(n,BindingFlags.Instance|BindingFlags.NonPublic).GetValue(o);}static object Call(object o,string n,params object[] a){return o.GetType().GetMethod(n,BindingFlags.Instance|BindingFlags.NonPublic).Invoke(o,a);}
 static void Check(string n,bool v){Console.WriteLine((v?"PASS ":"FAIL ")+n);if(!v)failures++;}
 [STAThread]static int Main(string[] args){var app=new Application{ShutdownMode=ShutdownMode.OnExplicitShutdown};Window pet=null;try{Directory.CreateDirectory(args[0]);pet=(Window)Activator.CreateInstance(typeof(ConanPet),true);pet.Show();((DispatcherTimer)Get(pet,"ticker")).Stop();((DispatcherTimer)Get(pet,"skillTicker")).Stop();var frames=(BitmapSource[,])Get(pet,"frames");var sprite=(SpriteView)Get(pet,"sprite");double scale=(double)Get(pet,"scale");Call(pet,"DisplayFrame",1,ActionTiming.WalkFrame(24,scale),.1,24.0);Check("running reuses exact original atlas frame",Object.ReferenceEquals(sprite.Frame,frames[1,ActionTiming.WalkFrame(24,scale)]));double before=((TranslateTransform)Get(pet,"bodyMove")).Y;Call(pet,"DisplayFrame",1,ActionTiming.WalkFrame(24,scale),5.0,24.0);Check("same distance keeps same bounce regardless of timer",before==((TranslateTransform)Get(pet,"bodyMove")).Y);Call(pet,"DisplayFrame",1,0,5.0,0.0);Check("no distance gives no artificial running bounce",((TranslateTransform)Get(pet,"bodyMove")).Y==0);
 var brush=new SolidColorBrush(Color.FromRgb(18,38,53));for(int i=0;i<64;i++){double t=i*.04,distance=t*100;var visual=new DrawingVisual();RenderOptions.SetBitmapScalingMode(visual,BitmapScalingMode.NearestNeighbor);using(var dc=visual.RenderOpen()){dc.DrawRectangle(brush,null,new Rect(0,0,820,310));var font=new Typeface("Microsoft YaHei UI");dc.DrawText(new FormattedText("原版步频",System.Globalization.CultureInfo.InvariantCulture,FlowDirection.LeftToRight,font,18,Brushes.White),new Point(45,18));dc.DrawText(new FormattedText("换腿减慢 1/3 · 原版形象",System.Globalization.CultureInfo.InvariantCulture,FlowDirection.LeftToRight,font,18,Brushes.White),new Point(435,18));dc.DrawLine(new Pen(Brushes.SlateGray,1),new Point(410,10),new Point(410,290));int old=(int)(distance/8)%8,next=ActionTiming.WalkFrame(distance,1);double bounceOld=-Math.Abs(Math.Sin(t*10))*2,bounceNew=-Math.Abs(Math.Sin(ActionTiming.WalkPhase(distance,1)*Math.PI*2))*2;dc.DrawImage(frames[1,old],new Rect(20+distance*.45,65+bounceOld,192,208));dc.DrawImage(frames[1,next],new Rect(430+distance*.45,65+bounceNew,192,208));}var bitmap=new RenderTargetBitmap(820,310,96,96,PixelFormats.Pbgra32);bitmap.Render(visual);var encoder=new PngBitmapEncoder();encoder.Frames.Add(BitmapFrame.Create(bitmap));using(var f=File.Create(Path.Combine(args[0],"run-"+i.ToString("D3")+".png")))encoder.Save(f);}Console.WriteLine("PREVIEW "+args[0]);
 }catch(Exception e){Console.WriteLine(e);failures++;}finally{if(pet!=null)pet.Close();app.Shutdown();}Console.WriteLine("Failures: "+failures);return failures==0?0:1;}
}
